<script setup>
import { api } from '../services/api'
import { useRequest } from '../composables/useRequest'
const {data,loading,error,reload}=useRequest(async signal=>(await api.get('/users/1',{signal})).data)
</script>
<template><div class="page-heading"><div><div class="eyebrow">THE PERSON BEHIND THE PROGRESS</div><h1>Your student profile.</h1><p>A little about you and your learning journey.</p></div><a-button @click="reload" :loading="loading">Refresh profile</a-button></div><a-alert v-if="error" type="error" :message="error" show-icon><template #action><a-button @click="reload">Try again</a-button></template></a-alert><a-skeleton v-else-if="loading" active avatar :paragraph="{rows:6}"/><template v-else-if="data"><div class="profile-banner"><a-avatar :size="80" style="background:#d6e4c7;color:#245d4e">{{data.name.split(' ').map(n=>n[0]).slice(0,2).join('')}}</a-avatar><div><span class="eyebrow">DEMO STUDENT · API PROFILE</span><h2>{{data.name}}</h2><p>@{{data.username}} <a-tag color="green">Active student</a-tag></p></div></div><a-card title="Personal information" class="profile-info"><a-descriptions :column="{xs:1,sm:1,md:2}" :colon="false"><a-descriptions-item label="Full name">{{data.name}}</a-descriptions-item><a-descriptions-item label="Email">{{data.email}}</a-descriptions-item><a-descriptions-item label="Phone">{{data.phone}}</a-descriptions-item><a-descriptions-item label="Website">{{data.website}}</a-descriptions-item><a-descriptions-item label="City">{{data.address.city}}</a-descriptions-item><a-descriptions-item label="Address">{{data.address.street}}, {{data.address.suite}}</a-descriptions-item><a-descriptions-item label="Organization">{{data.company.name}}</a-descriptions-item><a-descriptions-item label="Postal code">{{data.address.zipcode}}</a-descriptions-item></a-descriptions></a-card><p class="data-note">This page displays the sample user returned by JSONPlaceholder, not your personal account information.</p></template></template>
